properties.query:
let bad_tlds = dynamic([".xyz",".top",".click",".tk",".gq",".cf",".ml",".icu",".rest",".country",".buzz",".cyou"]);
let dyn_dns = dynamic(["duckdns.org","no-ip.com","no-ip.org","ddns.net","hopto.org","zapto.org","dynu.net","dnsexit.com","sytes.net","myftp.org","servehttp.com"]);
DeviceNetworkEvents
| where TimeGenerated > ago(24h)
| where ActionType in ("ConnectionSuccess","DnsConnectionInspected","ConnectionAttempt")
| where isnotempty(RemoteUrl)
| extend host = tolower(tostring(RemoteUrl))
| extend Domain = parse_url(host).Host
// Take the last label explicitly. Negative indexing of a dynamic array is not
// supported by the documented accessor semantics; derive the index from
// array_length instead so the expression is unambiguous.
| extend DomainLabels = split(Domain, ".")
| extend Tld = strcat(".", tostring(DomainLabels[array_length(DomainLabels) - 1]))
| where host has_any (dyn_dns) or Tld in (bad_tlds)
| project TimeGenerated, DeviceName, AccountName, host, Domain, Tld, RemoteIP,
          InitiatingProcessFileName, InitiatingProcessCommandLine
